head.script:
// 테스트 설명, 유효성 값 설정
//  - column_P_escapeFormatter_1.xml 에서 분리 : embeddedInput='true' 조건과 inputType='custom'(typeGetter) 조건만 검증
scwin.tData = {
    "description" : "[column > P > escapeFormatter]<br/>Column 의 표시값에 포함된 특수문자를 이스케이프 처리하는 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "Column 의 inputType='text' 이고 embeddedInput='true' 인 경우 읽기전용(readonly) 또는 비활성화(disabled) 상태인 Cell 에서만 동작합니다.",
        "Column 의 inputType='custom' 인 경우 typeGetter 함수로 결정된 inputType 에 따라 동작 여부가 정해집니다."
    ]
}



scwin.gVar = {
    // escapeFormatter 사용자 함수에 Row 인덱스별로 전달된 첫번째 파라미터 (Target 생성 시 초기화)
    "escapeParams" : {},
    // inputType='custom' 일 때 typeGetter 가 Row 별로 결정하는 inputType
    "customTypes" : ["text", "text", "text", "textarea", "link"]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    //  gdl_boolean 코드값 : 미설정='1' / true='2' / false='3'
    con_inputType.setValue("text");
    con_embeddedInput.setValue("2");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// escapeFormatter 로 지정하는 사용자 함수 : script 태그를 제거하고 밑줄(u 태그)로 감싸 반환
scwin.fmtEscape = function (data, rowIndex, colIndex) {
    scwin.gVar.escapeParams[rowIndex] = data;
    let reScript = new RegExp("<script.*?</scr" + "ipt>", "gi");
    return "<u>" + String(data).replace(reScript, "") + "</u>";
}



// inputType='custom' Column 의 typeGetter : Row 별 inputType 결정
scwin.getType = function (info) {
    let inputType = scwin.gVar.customTypes[info.rowIndex];
    return {
        id : "dynamic_" + inputType + "_" + info.rowIndex,
        inputType : inputType,
        options : {}
    };
}



// comp 생성
//  escapeFormatter 관련 속성은 렌더 시 결정되므로 con 변경 후 Target 재생성(btn_createTarget -> comp_init) 으로만 반영한다.
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }
    scwin.gVar.escapeParams = {};

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] escape=false, escapeFormatter=scwin.fmtEscape 고정 (script 태그 제거 후 u 태그로 감싸 반환)\n[전제] Row 1 은 읽기전용(readonly), Row 2 는 비활성화(disabled) Cell, 나머지 Row 는 편집 가능\n[전제] inputType=custom 이면 typeGetter 가 Row 0~2 는 text, Row 3 은 textarea, Row 4 는 link 반환\n[확인] DataList 값 -> 첫번째 파라미터 -> 셀 표시값(해석된 태그), 내장 입력창이면 입력창 값"', '', 'label1');

    // 조건 (gdl_boolean 은 getText 로 라벨('' / 'true' / 'false') 을 읽는다)
    let cInputType = con_inputType.getValue();
    let cEmbeddedInput = con_embeddedInput.getText();

    // dataList 생성 (특수문자 포함 값은 setJSON 으로 주입)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="val" name="val" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    let strScript = "<script>alert('XSS')</scr" + "ipt>";
    dlt_bind.setJSON([
        { "val" : strScript + "<b>긴급</b> 반품 요청" },
        { "val" : strScript + "<b>일반</b> 교환 요청" },
        { "val" : strScript + "<b>보류</b> 환불 요청" },
        { "val" : strScript + "<b>완료</b> 배송 문의" },
        { "val" : strScript + "<b>취소</b> 주문 문의" }
    ], false);

    // val Column 속성 (미설정 옵션은 속성 자체를 넣지 않는다)
    let attrVal = ' inputType="' + cInputType + '" escape="false" escapeFormatter="scwin.fmtEscape"';
    if (cEmbeddedInput !== '') {
        attrVal += ' embeddedInput="' + cEmbeddedInput + '"';
    }
    if (cInputType === "custom") {
        attrVal += ' typeGetter="scwin.getType"';
    }

    let headerText = "val (" + cInputType + " / embeddedInput " + (cEmbeddedInput === '' ? "미설정" : cEmbeddedInput) + ")";

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:700px;height:190px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="680" style="" inputType="text" id="column1" value="' + headerText + '"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="680" style="" id="val" value=""' + attrVal + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // Row 1 은 읽기전용(readonly), Row 2 는 비활성화(disabled) Cell 로 설정
    if (scwin["target1"]) {
        target1.setCellReadOnly(1, "val", true);
        target1.setCellDisabled(2, "val", true);
    }
}



// val 셀의 화면 표시값과 해석된 태그
//  - 내장 입력창이 있으면 입력창 값, 그 외는 표시 영역 텍스트와 생성된 HTML 요소(태그 해석 : 태그명)
scwin.getCellStr = function (rowIndex) {
    let td = document.querySelector("td[id*='" + target1.id + "_cell_" + rowIndex + "_0']");
    if (!td) {
        return "Cell 없음";
    }
    let input = td.querySelector("input, textarea");
    if (input) {
        return "입력창 값 '" + input.value + "'";
    }
    let wrap = td.querySelector("a") || td.querySelector("nobr, span.w2grid_span, div.w2grid_textarea") || td;
    let str = "'" + wrap.textContent + "'";
    let tags = [];
    let elems = wrap.querySelectorAll("*");
    for (let i = 0; i < elems.length; i++) {
        let tagName = elems[i].tagName.toLowerCase();
        if (tags.indexOf(tagName) < 0) {
            tags.push(tagName);
        }
    }
    if (tags.length > 0) {
        str += "(태그 해석 : " + tags.join(", ") + ")";
    }
    return str;
}



// 전체 Row 의 DataList 값 -> 첫번째 파라미터 -> 셀 표시값 출력
//  - validation 1 : embeddedInput='true' 일 때 편집 가능 Row(0, 3, 4) 는 호출 안 됨 / 입력창 값, readonly(Row 1), disabled(Row 2) Row 는 반환값 표시
//  - validation 2 : inputType='custom' 일 때 typeGetter 결과(text / textarea / link) 별 호출 여부와 표시값
scwin.btn_checkCell_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let param = scwin.gVar.escapeParams[i];
        let arrText = ["Row " + i + " '" + dlt_bind.getCellData(i, "val") + "'"];
        arrText.push("첫번째 파라미터 " + (typeof param === "undefined" ? "호출 안 됨" : "'" + param + "'"));
        arrText.push(scwin.getCellStr(i));
        bottom.setReturnValue(arrText.join(" -> "));
    }
}
